import 'package:flutter/material.dart';\nimport 'package:intl/intl.dart';\n\nclass memberEarningPage extends StatefulWidget {\n  const memberEarningPage({super.key});\n\n  @override\n  State<memberEarningPage> createState() => _memberEarningPageState();\n}\n\nclass _memberEarningPageState extends State<memberEarningPage> {\n  // Sample earnings data\n  final List<Map<String, dynamic>> _earnings = [\n    {\n      'date': DateTime.now().subtract(const Duration(days: 1)),\n      'amount': 125.50,\n      'source': 'Content Creation',\n      'status': 'Completed',\n    },\n    {\n      'date': DateTime.now().subtract(const Duration(days: 3)),\n      'amount': 85.25,\n      'source': 'Referral Bonus',\n      'status': 'Completed',\n    },\n    {\n      'date': DateTime.now().subtract(const Duration(days: 5)),\n      'amount': 200.00,\n      'source': 'Premium Subscription',\n      'status': 'Pending',\n    },\n    {\n      'date': DateTime.now().subtract(const Duration(days: 7)),\n      'amount': 45.75,\n      'source': 'Ad Revenue',\n      'status': 'Completed',\n    },\n  ];\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('member Earnings'),\n        backgroundColor: Colors.grey[850],\n        foregroundColor: Colors.white,\n      ),\n      body: Padding(\n        padding: const EdgeInsets.all(16.0),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // Total earnings card\n            Container(\n              padding: const EdgeInsets.all(16),\n              decoration: BoxDecoration(\n                color: Colors.grey[800],\n                borderRadius: BorderRadius.circular(8),\n              ),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  const Text(\n                    'Total Earnings',\n                    style: TextStyle(\n                      fontSize: 16,\n                      color: Colors.grey,\n                    ),\n                  ),\n                  const SizedBox(height: 8),\n                  Text(\n                    '\$456.50',\n                    style: const TextStyle(\n                      fontSize: 32,\n                      fontWeight: FontWeight.bold,\n                      color: Colors.white,\n                    ),\n                  ),\n                  const SizedBox(height: 8),\n                  Row(\n                    mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                    children: [\n                      _buildEarningStat('This Month', '\$185.25'),\n                      _buildEarningStat('This Week', '\$65.75'),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n            const SizedBox(height: 16),\n            const Text(\n              'Recent Earnings',\n              style: TextStyle(\n                fontSize: 20,\n                fontWeight: FontWeight.bold,\n              ),\n            ),\n            const SizedBox(height: 8),\n            Expanded(\n              child: ListView.builder(\n                itemCount: _earnings.length,\n                itemBuilder: (context, index) {\n                  final earning = _earnings[index];\n                  return Card(\n                    color: Colors.grey[800],\n                    child: ListTile(\n                      contentPadding: const EdgeInsets.symmetric(\n                        horizontal: 16,\n                        vertical: 8,\n                      ),\n                      leading: Container(\n                        padding: const EdgeInsets.all(8),\n                        decoration: BoxDecoration(\n                          color: earning['status'] == 'Completed'\n                              ? Colors.green[800]\n                              : Colors.orange[800],\n                          borderRadius: BorderRadius.circular(6),\n                        ),\n                        child: Text(\n                          '+\${earning['amount'].toStringAsFixed(2)}',\n                          style: const TextStyle(\n                            fontWeight: FontWeight.bold,\n                            color: Colors.white,\n                          ),\n                        ),\n                      ),\n                      title: Text(\n                        earning['source'],\n                        style: const TextStyle(\n                          fontWeight: FontWeight.w500,\n                        ),\n                      ),\n                      subtitle: Text(\n                        DateFormat('MMM dd, yyyy').format(earning['date']),\n                      ),\n                      trailing: Container(\n                        padding: const EdgeInsets.symmetric(\n                          horizontal: 8,\n                          vertical: 4,\n                        ),\n                        decoration: BoxDecoration(\n                          color: earning['status'] == 'Completed'\n                              ? Colors.green[800]\n                              : Colors.orange[800],\n                          borderRadius: BorderRadius.circular(12),\n                        ),\n                        child: Text(\n                          earning['status'],\n                          style: const TextStyle(\n                            fontSize: 12,\n                            color: Colors.white,\n                          ),\n                        ),\n                      ),\n                    ),\n                  );\n                },\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildEarningStat(String label, String value) {\n    return Column(\n      crossAxisAlignment: CrossAxisAlignment.start,\n      children: [\n        Text(\n          label,\n          style: const TextStyle(\n            fontSize: 12,\n            color: Colors.grey,\n          ),\n        ),\n        const SizedBox(height: 4),\n        Text(\n          value,\n          style: const TextStyle(\n            fontSize: 16,\n            fontWeight: FontWeight.bold,\n            color: Colors.white,\n          ),\n        ),\n      ],\n    );\n  }\n}
